<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><div class="page-head"><h1>Staff</h1><a class="button primary" href="<?= site_url('users/create') ?>">Add Staff</a></div><div class="panel"><table><thead><tr><th>Avatar</th><th>Full name</th><th>Username</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?php if($u['avatar']): ?><img class="avatar" src="<?= base_url('uploads/avatars/'.$u['avatar']) ?>" alt=""><?php else: ?><span class="avatar fallback"><?= esc(strtoupper(substr($u['full_name'],0,1))) ?></span><?php endif ?></td><td><?= esc($u['full_name']) ?></td><td><?= esc($u['username']) ?></td><td><?= $u['is_active']?'Active':'Archived' ?></td><td><a href="<?= site_url('users/'.$u['id'].'/edit') ?>">Edit</a><?php if($u['is_active']): ?><form class="inline" method="post" action="<?= site_url('users/'.$u['id'].'/archive') ?>" onsubmit="return confirm('Archive this staff account?')"><?= csrf_field() ?><button class="danger link">Archive</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?= $this->endSection() ?>
